<?php
/** Flag-independent installed month controls; no financial entries or automatic closing. */
require_once __DIR__.'/reporting_common.php';
function periods_trigger_contract(): array
{
    $out=[];foreach(['r5_bundle_immutable'=>['complete_report_bundles','Submitted complete reports are immutable'],'r5_bundle_review'=>['complete_report_reviews','Complete report reviews are immutable'],'r5_period_event'=>['accounting_period_events','Period events are immutable']] as $prefix=>[$table,$text])foreach(['update'=>'UPDATE','delete'=>'DELETE'] as $suffix=>$event)$out[$prefix.'_'.$suffix]=[$table,$event,"BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='$text'; END"];
    $out['r5_bundle_root_delete']=['complete_report_roots','DELETE',"BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Complete report sequence history is retained'; END"];
    $out['r5_period_root_delete']=['accounting_period_roots','DELETE',"BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Period control history is retained'; END"];return $out;
}
function periods_schema(PDO $pdo): array
{
    $tables=['complete_report_roots','complete_report_bundles','complete_report_reviews','accounting_period_roots','accounting_period_events'];$found=$pdo->query("SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('complete_report_roots','complete_report_bundles','complete_report_reviews','accounting_period_roots','accounting_period_events')")->fetchAll(PDO::FETCH_COLUMN);if(!$found)return ['state'=>'absent','complete'=>false];if(count($found)!==5)return ['state'=>'partial','complete'=>false];
    try{
        foreach(['complete_report_roots'=>'id,report_month,next_revision','complete_report_bundles'=>'id,root_id,revision_number,period_epoch,prepared_by,prepared_at,prepared_name,request_key,request_hash,source_fingerprint,payload_hash,payload','complete_report_reviews'=>'id,bundle_id,decision,reason,actor_id,actor_name,reviewed_at,request_key,request_hash','accounting_period_roots'=>'id,period_month,state,epoch,closing_bundle_id,closing_review_id,last_event_id','accounting_period_events'=>'id,event_kind,actor_id,actor_name,event_at,reason,request_key,request_hash,payload,payload_hash'] as $table=>$cols)$pdo->query('SELECT '.$cols.' FROM '.$table.' LIMIT 0');
        $triggers=[];foreach($pdo->query('SHOW TRIGGERS') as $t)$triggers[$t['Trigger']]=$t;$normal=static fn($s)=>strtolower(preg_replace('/[\s`]+/u','',$s));foreach(periods_trigger_contract() as $name=>[$table,$event,$body])if(!isset($triggers[$name])||$triggers[$name]['Table']!==$table||$triggers[$name]['Timing']!=='BEFORE'||$triggers[$name]['Event']!==$event||$normal($triggers[$name]['Statement'])!==$normal($body))return ['state'=>'partial','complete'=>false];
        foreach(['complete_report_roots'=>[['report_month']],'complete_report_bundles'=>[['root_id','revision_number'],['prepared_by','request_key']],'complete_report_reviews'=>[['bundle_id'],['actor_id','request_key']],'accounting_period_roots'=>[['period_month']],'accounting_period_events'=>[['actor_id','request_key']]] as $table=>$required){$indexes=[];foreach($pdo->query('SHOW INDEX FROM '.$table) as $i)if((int)$i['Non_unique']===0)$indexes[$i['Key_name']][(int)$i['Seq_in_index']]=$i['Column_name'];$unique=[];foreach($indexes as $cols){ksort($cols);$unique[]=array_values($cols);}foreach($required as $cols)if(!in_array($cols,$unique,true))return ['state'=>'partial','complete'=>false];}
        $keys=[];foreach($pdo->query("SELECT CONSTRAINT_NAME,TABLE_NAME,COLUMN_NAME,REFERENCED_TABLE_NAME,REFERENCED_COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND REFERENCED_TABLE_SCHEMA=DATABASE() AND (CONSTRAINT_NAME LIKE 'r5_bundle_%' OR CONSTRAINT_NAME LIKE 'r5_period_%')") as $k)$keys[$k['CONSTRAINT_NAME']]=[$k['TABLE_NAME'],$k['COLUMN_NAME'],$k['REFERENCED_TABLE_NAME'],$k['REFERENCED_COLUMN_NAME']];
        foreach(['r5_bundle_root'=>['complete_report_bundles','root_id','complete_report_roots','id'],'r5_bundle_preparer'=>['complete_report_bundles','prepared_by','user_identities','UserID'],'r5_bundle_review_bundle'=>['complete_report_reviews','bundle_id','complete_report_bundles','id'],'r5_bundle_reviewer'=>['complete_report_reviews','actor_id','user_identities','UserID'],'r5_period_actor'=>['accounting_period_events','actor_id','user_identities','UserID'],'r5_period_bundle'=>['accounting_period_roots','closing_bundle_id','complete_report_bundles','id'],'r5_period_review'=>['accounting_period_roots','closing_review_id','complete_report_reviews','id'],'r5_period_event'=>['accounting_period_roots','last_event_id','accounting_period_events','id']] as $key=>$shape)if(($keys[$key]??null)!==$shape)return ['state'=>'partial','complete'=>false];
        foreach($pdo->query('SELECT r.next_revision,COALESCE(MAX(b.revision_number),0) max_revision FROM complete_report_roots r LEFT JOIN complete_report_bundles b ON b.root_id=r.id GROUP BY r.id') as $r)if((int)$r['next_revision']!==(int)$r['max_revision']+1)return ['state'=>'partial','complete'=>false];
        foreach($pdo->query('SELECT * FROM accounting_period_roots ORDER BY period_month') as $r){if(substr($r['period_month'],8,2)!=='01')return ['state'=>'partial','complete'=>false];if((int)$r['epoch']===0){if($r['state']!=='Open'||$r['last_event_id']!==null||$r['closing_bundle_id']!==null||$r['closing_review_id']!==null)return ['state'=>'partial','complete'=>false];continue;}$s=$pdo->prepare('SELECT * FROM accounting_period_events WHERE id=?');$s->execute([$r['last_event_id']]);$e=$s->fetch(PDO::FETCH_ASSOC);if(!$e||!hash_equals($e['payload_hash'],hash('sha256',reporting_json(json_decode($e['payload'],true,64,JSON_THROW_ON_ERROR)))))return ['state'=>'partial','complete'=>false];$members=json_decode($e['payload'],true,64,JSON_THROW_ON_ERROR);$member=$members[substr($r['period_month'],0,7)]??null;if(!$member||(int)$member['new_epoch']!==(int)$r['epoch']||$member['state']!==$r['state'])return ['state'=>'partial','complete'=>false];if($r['state']==='Closed'){if($e['event_kind']!=='Closed'||(int)$member['bundle_id']!==(int)$r['closing_bundle_id']||(int)$member['review_id']!==(int)$r['closing_review_id'])return ['state'=>'partial','complete'=>false];$s=$pdo->prepare("SELECT COUNT(*) FROM complete_report_reviews v JOIN complete_report_bundles b ON b.id=v.bundle_id JOIN complete_report_roots m ON m.id=b.root_id WHERE v.id=? AND b.id=? AND v.decision='Reviewed' AND m.report_month=?");$s->execute([$r['closing_review_id'],$r['closing_bundle_id'],$r['period_month']]);if((int)$s->fetchColumn()!==1)return ['state'=>'partial','complete'=>false];}elseif($r['closing_bundle_id']!==null||$r['closing_review_id']!==null||$e['event_kind']!=='Reopened')return ['state'=>'partial','complete'=>false];}
        return ['state'=>'complete','complete'=>true];
    }catch(Throwable $e){return ['state'=>'partial','complete'=>false];}
}
function periods_require(PDO $pdo):void{if(!periods_schema($pdo)['complete'])throw new ReportingProblem('Monthly controls are unavailable until deployment is complete.',503);}
/** Caller already holds active actor + shared write barrier, before downstream locks. */
function periods_basis_guard(PDO $pdo,string $from,?string $to=null):void
{
    $schema=periods_schema($pdo);if($schema['state']==='absent')return;if(!$schema['complete'])throw new ReportingProblem('Monthly controls need a deployment integrity review. This change was not saved.',503);if(!$pdo->inTransaction())throw new LogicException('Period checks require the shared writer transaction.');$from=accounting_date($from);if($to!==null){$to=accounting_date($to);if($to<$from)throw new LogicException('Invalid dependent period interval.');}
    $sql="SELECT period_month FROM accounting_period_roots WHERE state='Closed' AND period_month>=?";$args=[substr($from,0,7).'-01'];if($to!==null){$sql.=' AND period_month<=?';$args[]=substr($to,0,7).'-01';}$s=$pdo->prepare($sql.' ORDER BY period_month FOR UPDATE');$s->execute($args);$months=array_map(fn($d)=>substr($d,0,7),$s->fetchAll(PDO::FETCH_COLUMN));if($months)throw new ReportingProblem('This change affects closed month'.(count($months)>1?'s ':' ').implode(', ',$months).'. Ask Management to reopen the affected month and later closed months before making this change.',409);
}
/** A later correction may invalidate an earlier configured investment trace. */
function periods_correction_from(PDO $pdo,string $date,int $target):string
{
    $date=accounting_date($date);$schema=periods_schema($pdo);if($schema['state']==='absent')return $date;if(!$schema['complete'])throw new ReportingProblem('Monthly controls need a deployment integrity review.',503);require_once __DIR__.'/report_configuration.php';report_configuration_require($pdo);$s=$pdo->prepare("SELECT period_month FROM accounting_period_roots WHERE state='Closed' AND period_month<? ORDER BY period_month");$s->execute([substr($date,0,7).'-01']);foreach($s->fetchAll(PDO::FETCH_COLUMN) as $month){$cfg=report_configuration_current($pdo,$month);if(!$cfg)throw new ReportingProblem('A closed month is missing its reporting setup. Resolve its integrity before correcting this transaction.',503);$payload=$cfg['payload'];foreach($payload['advance_dependencies']??[] as $dependency){$release=$pdo->prepare('SELECT entry_date FROM journal_entries WHERE id=?');$release->execute([$dependency['release_journal']]);$releaseDate=$release->fetchColumn();if(!$releaseDate)throw new ReportingProblem('A reporting investment dependency needs an integrity review.',503);if($releaseDate<=reporting_month_range(substr($month,0,7))[1]&&in_array($target,[(int)$dependency['release_journal'],(int)$dependency['liquidation_journal']],true))return $month;}}return $date;
}
function periods_root(PDO $pdo,string $month,bool $lock=false,bool $create=false):array
{
    $month=reporting_month($month);if($create)$pdo->prepare('INSERT INTO accounting_period_roots(period_month) VALUES(?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)')->execute([$month.'-01']);$s=$pdo->prepare('SELECT * FROM accounting_period_roots WHERE period_month=?'.($lock?' FOR UPDATE':''));$s->execute([$month.'-01']);return $s->fetch(PDO::FETCH_ASSOC)?:['id'=>null,'period_month'=>$month.'-01','state'=>'Open','epoch'=>0,'closing_bundle_id'=>null,'closing_review_id'=>null,'last_event_id'=>null];
}
function periods_reopen_set(PDO $pdo,string $month,bool $lock=false):array
{
    $s=$pdo->prepare("SELECT period_month,epoch FROM accounting_period_roots WHERE state='Closed' AND period_month>=? ORDER BY period_month".($lock?' FOR UPDATE':''));$s->execute([reporting_month($month).'-01']);$set=[];foreach($s as $r)$set[substr($r['period_month'],0,7)]=(int)$r['epoch'];return $set;
}
function periods_request(array $r):array
{
    reporting_csrf($r);$month=reporting_month($r['month']??'');$reason=reporting_text($r['reason']??'',2000,'reason',true);$key=reporting_text($r['request_key']??'',64,'request identity',true);if(!preg_match('/\A[a-f0-9]{64}\z/',$key))throw new ReportingProblem('Reload this month before confirming.',400);return [$month,$reason,$key];
}
function periods_epoch($value):int{if(is_int($value)&&$value>=0&&$value<=4294967295)return $value;if(is_string($value)&&preg_match('/\A(?:0|[1-9][0-9]{0,9})\z/',$value)&&(int)$value<=4294967295)return (int)$value;throw new ReportingProblem('Reload the current month state before confirming.',400);}
function periods_existing(PDO $pdo,int $uid,string $key,string $hash):?array
{
    $s=$pdo->prepare('SELECT id,request_hash,payload,payload_hash,event_kind FROM accounting_period_events WHERE actor_id=? AND request_key=?');$s->execute([$uid,$key]);$e=$s->fetch(PDO::FETCH_ASSOC);if(!$e)return null;if(!hash_equals($hash,$e['request_hash']))throw new ReportingProblem('That request identity was already used for a different month action.',409);$payload=json_decode($e['payload'],true,64,JSON_THROW_ON_ERROR);if(!hash_equals($e['payload_hash'],hash('sha256',reporting_json($payload))))throw new ReportingProblem('The saved month action needs an integrity review.',503);return ['event_id'=>(int)$e['id'],'kind'=>$e['event_kind'],'months'=>array_keys($payload),'duplicate'=>true];
}
function periods_event(PDO $pdo,array $actor,string $kind,string $reason,string $key,string $requestHash,array $members):int
{
    $s=$pdo->prepare('INSERT INTO accounting_period_events(event_kind,actor_id,actor_name,event_at,reason,request_key,request_hash,payload,payload_hash) VALUES(?,?,?,UTC_TIMESTAMP(),?,?,?,?,?)');$json=reporting_json($members);$s->execute([$kind,$actor['UserID'],$actor['FullName'],$reason,$key,$requestHash,$json,hash('sha256',$json)]);return (int)$pdo->lastInsertId();
}
function periods_close(PDO $pdo,int $uid,array $r):array
{
    [$month,$reason,$key]=periods_request($r);$bundle=reporting_id($r['bundle_id']??null,'reviewed complete report');$epoch=periods_epoch($r['expected_epoch']??null);$requestHash=hash('sha256',reporting_json(['Closed',$month,$reason,$bundle,$epoch]));periods_require($pdo);require_once __DIR__.'/report_bundles.php';
    return reporting_tx($pdo,$uid,['Management'],function($actor)use($pdo,$uid,$month,$reason,$key,$bundle,$epoch,$requestHash){periods_require($pdo);if($old=periods_existing($pdo,$uid,$key,$requestHash))return $old;if(reporting_month_range($month)[1]>=substr(accounting_today(),0,7).'-01')throw new ReportingProblem('Close only a fully elapsed month.',422);$root=periods_root($pdo,$month,true,true);if($root['state']!=='Open'||(int)$root['epoch']!==$epoch)throw new ReportingProblem('This month state changed. Reload it before closing.',409);$frozen=report_bundle_load($pdo,$uid,$bundle,false);if($frozen['month']!==$month||$frozen['state']!=='Reviewed'||(int)$frozen['period_epoch']!==$epoch)throw new ReportingProblem('Prepare and review a new complete report revision for this open month before closing.',409);$live=report_bundle_model($pdo,$uid,$month);if(!$live['complete']||!hash_equals($frozen['source_fingerprint'],$live['fingerprint']))throw new ReportingProblem('The reviewed reports are stale. Submit and review a current complete revision before closing.',409);$members=[$month=>['prior_epoch'=>$epoch,'new_epoch'=>$epoch+1,'state'=>'Closed','bundle_id'=>$bundle,'review_id'=>(int)$frozen['review']['id']]];$event=periods_event($pdo,$actor,'Closed',$reason,$key,$requestHash,$members);$pdo->prepare("UPDATE accounting_period_roots SET state='Closed',epoch=epoch+1,closing_bundle_id=?,closing_review_id=?,last_event_id=? WHERE id=?")->execute([$bundle,$frozen['review']['id'],$event,$root['id']]);reporting_audit($pdo,$uid,AUDIT_ACTION_EDIT,'Month close',$event,null,['month'=>$month,'bundle_id'=>$bundle,'reason'=>$reason,'epoch'=>$epoch+1]);stage1_write_changed($pdo);return ['event_id'=>$event,'kind'=>'Closed','months'=>[$month],'duplicate'=>false];});
}
function periods_reopen(PDO $pdo,int $uid,array $r):array
{
    [$month,$reason,$key]=periods_request($r);$set=$r['expected_set']??null;if(!is_array($set)||array_is_list($set)||!$set||count($set)>240)throw new ReportingProblem('Review the affected months before reopening.',400);$expected=[];foreach($set as $m=>$e){$m=reporting_month($m);if(!is_int($e)||$e<1)throw new ReportingProblem('Reload the affected month states.',400);$expected[$m]=$e;}ksort($expected);if(array_key_first($expected)!==$month)throw new ReportingProblem('Choose the earliest closed month shown for reopening.',400);$hash=hash('sha256',reporting_json(['Reopened',$month,$reason,$expected]));periods_require($pdo);
    return reporting_tx($pdo,$uid,['Management'],function($actor)use($pdo,$uid,$month,$reason,$key,$expected,$hash){periods_require($pdo);if($old=periods_existing($pdo,$uid,$key,$hash))return $old;$actual=periods_reopen_set($pdo,$month,true);if($actual!==$expected)throw new ReportingProblem('The affected closed months changed. Review the full month list again before confirming.',409);$members=[];foreach($actual as $m=>$epoch)$members[$m]=['prior_epoch'=>$epoch,'new_epoch'=>$epoch+1,'state'=>'Open'];$event=periods_event($pdo,$actor,'Reopened',$reason,$key,$hash,$members);foreach($actual as $m=>$epoch)$pdo->prepare("UPDATE accounting_period_roots SET state='Open',epoch=epoch+1,closing_bundle_id=NULL,closing_review_id=NULL,last_event_id=? WHERE period_month=?")->execute([$event,$m.'-01']);reporting_audit($pdo,$uid,AUDIT_ACTION_EDIT,'Month reopen',$event,null,['months'=>$actual,'reason'=>$reason]);stage1_write_changed($pdo);return ['event_id'=>$event,'kind'=>'Reopened','months'=>array_keys($actual),'duplicate'=>false];});
}
